INSERT INTO manufacturers (name, legal_name, website, notes) VALUES
('Super5', NULL, 'super5.com.br', 'Fabricante de ferragens para vidro temperado. Catálogo eletrônico "Super Catálogo de Ferragens para Vidros Temperados", 54 páginas. Telefone impresso no rodapé do catálogo: +55 41 3249-5555.');
INSERT INTO technical_sources (manufacturer_id, title, file_name, document_type, is_uploaded, page_count, notes) VALUES
(@mfr_super5, 'Super Catálogo de Ferragens para Vidros Temperados (Super5)', 'CatalogoFerragensVidroSuper5.pdf', 'CATALOGO', 1, 54, 'Págs. 1 (capa) e 54 (tabela de cores de acabamento, não geram linha de acessório) fora da contagem de itens. Cada item mostra: código, nome/aplicação, foto do produto e desenho esquemático de montagem (furação/pontos de fixação), sem cota de tipologia formal explícita -- a aplicação é extraída do próprio nome impresso.');
